# Acceptance of delegation + audio (prompt 2, § 2 and § 8). Self-contained: every sound here is generated by the skill's own
# scripts (synth_music.py, a synthetic voice-like signal), so the test runs from a clean checkout with no library.
#   python tests/run_autonomia_audio.py
# 1 delegation table (6 requests) → mode, delegated/reserved stages, constraints, questions asked
# 2 music choice: best fit has no verifiable licence → next viable track chosen, substitution + cost reported; hybrid A/B
#   on the same window with comparable loudness
# 3 mono cancellation found in the faulty interval, declared silence kept, corrected version passes (decoded MP4)
# 4 voice keyword masked by the music → the music ducks in that interval → keyword SNR measured before/after
# 5 timbre revision "deixe a confirmação menos estridente": one variable (low-pass), contact frame stable in the decoded MP4,
#   other stems bit-identical, brightness measured lower; peak re-alignment risk checked explicitly
import sys as _s0
for _st in (_s0.stdout, _s0.stderr):
    try: _st.reconfigure(encoding="utf-8")
    except Exception: pass
import os, sys, json, subprocess, shutil, wave
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE); os.chdir(ROOT)
sys.path.insert(0, 'scripts'); from lib.tools import find_tool; from lib import delegation as D
FF = find_tool('ffmpeg'); PY = sys.executable; W = 'tests/_work/autonomia'; EV = 'tests/evidence/12-autonomia-audio'
shutil.rmtree(W, ignore_errors=True); os.makedirs(W); os.makedirs(EV, exist_ok=True); SR = 48000
res = []
def check(name, ok, detail): res.append({'name': name, 'result': 'PASSOU' if ok else 'FALHOU', 'detail': detail}); print(('PASSOU' if ok else 'FALHOU'), name, '·', detail)
def run(*a): r = subprocess.run(list(a), capture_output=True, text=True, encoding='utf8', errors='replace'); return r.returncode, r.stdout + r.stderr
def wav(path, y):
    y = np.clip(y, -1, 1); y2 = y if y.ndim == 2 else np.stack([y, y], 1)
    with wave.open(path, 'wb') as w: w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR); w.writeframes((y2 * 32767).astype('<i2').tobytes())
def dec(p, ch=2): return np.frombuffer(subprocess.run([FF, '-v', 'error', '-i', p, '-ac', str(ch), '-ar', str(SR), '-f', 'f32le', '-'], capture_output=True).stdout, np.float32).reshape(-1, ch)
def to_mp4(a, out, dur):
    subprocess.run([FF, '-v', 'error', '-y', '-f', 'lavfi', '-i', f'color=c=black:s=320x180:r=30:d={dur}', '-i', a, '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-b:a', '256k', '-shortest', out], check=True)

# ---------------------------------------------------------------- 1 delegation table
cases = [
 ('Faça o comercial inteiro, decide tudo.', dict(mode='autonomo', reserved=[], questions=0)),
 ('O storyboard já está aprovado. Cuide de todo o som.', dict(mode='hibrido', approved=['storyboard'], delegated_has=['musica', 'foley', 'locucao', 'mix'])),
 ('Faça tudo, mas quero escolher a música.', dict(mode='hibrido', reserved=['musica'], questions=1)),
 ('Faça tudo, sem locução.', dict(mode='autonomo', voz=False, questions=0)),
 ('Faça tudo.', dict(mode='autonomo', verba=0.0)),
 ('Faça tudo com a assinatura sonora oficial da minha marca.', dict(mode='autonomo', requires='assinatura-sonora', master='previa')),
]
for words, exp in cases:
    p = f'{W}/estado-{len(res)}'; st = D.init(p, words); q = [s for s in D.STAGES if D.gate(st, s)[0] == 'perguntar']
    ok = st['mode'] == exp['mode']
    if 'reserved' in exp: ok &= [s for s, d in st['decisions'].items() if d['status'] == 'aguardando-usuario'] == exp['reserved']
    if 'questions' in exp: ok &= len(q) == exp['questions']
    if 'approved' in exp: ok &= all(st['decisions'].get(s, {}).get('status') == 'aprovado-usuario' for s in exp['approved'])
    if 'delegated_has' in exp: ok &= all(st['decisions'].get(s, {}).get('status') == 'delegado-agente' for s in exp['delegated_has'])
    if 'voz' in exp: ok &= st['constraints'].get('voz') is False and D.gate(st, 'locucao')[0] == 'seguir'
    if 'verba' in exp: ok &= st['constraints'].get('verba') == 0.0
    if 'requires' in exp: ok &= any(r['id'] == exp['requires'] for r in st['requires'])
    if 'master' in exp: ok &= D.gate(st, 'master')[0] == exp['master']
    check(f'delegação: "{words}"', ok, f"modo {st['mode']}, perguntas {q or 'nenhuma'}, restrições {st['constraints']}")
# the hybrid sound-only delegation keeps the storyboard approval; a decision on a reserved stage is refused (one question)
st = D.init(f'{W}/res', 'Faça tudo, mas quero escolher a música.'); ok1, m1 = D.decide(st, 'musica', 'faixa X', 'gosto'); ok2, m2 = D.decide(st, 'foley', 'toque cerâmico', 'material')
check('híbrido: decidir a música é recusado, foley segue', (not ok1) and ok2 and st['decisions']['foley']['status'] == 'delegado-agente', f'música → "{m1}"; foley → {m2}')
st = D.init(f'{W}/aut', 'Faça o comercial inteiro, decide tudo.'); D.decide(st, 'musica', 'faixa B', 'drop no reveal'); D.save(f'{W}/aut', st)
st2 = D.load(f'{W}/aut'); check('estado distingue decisão delegada de aprovação humana', st2['decisions']['musica']['status'] == 'delegado-agente' and 'decide tudo' in st2['decisions']['musica']['scope'], st2['decisions']['musica']['scope'])

# ---------------------------------------------------------------- 2 music choice with licence filter
md = f'{W}/musicas'; os.makedirs(md)
for name, seed, mood in (('melhor-sem-licenca', 3, 'bright'), ('apta', 5, 'dark'), ('paga', 7, 'bright')):
    run(PY, 'scripts/synth_music.py', f'{md}/{name}.wav', '--len', '30', '--drop', '20', '--seed', str(seed), '--mood', mood, '--breath', '0.8' if name == 'melhor-sem-licenca' else '0.4')
cat = [{'file': 'melhor-sem-licenca.wav', 'title': 'melhor-sem-licenca', 'license': '?', 'verified': False, 'commercial': True, 'redistribute': True, 'content_id': False, 'cost': 0},
       {'file': 'apta.wav', 'title': 'apta', 'license': 'CC0 (autoria própria)', 'verified': True, 'commercial': True, 'redistribute': True, 'content_id': False, 'cost': 0},
       {'file': 'paga.wav', 'title': 'paga', 'license': 'loja', 'verified': True, 'commercial': True, 'redistribute': False, 'content_id': False, 'cost': 40}]
json.dump(cat, open(f'{md}/catalogo.json', 'w', encoding='utf8'), ensure_ascii=False)
c, out = run(PY, 'scripts/music_pick.py', f'{md}/catalogo.json', '--reveal', '14', '--len', '21', '--out', f'{EV}/escolha-musica.json', '--ab', f'{W}/ab')
pick = json.load(open(f'{EV}/escolha-musica.json', encoding='utf8'))
check('música: candidata sem licença verificável substituída pela próxima apta', c == 0 and pick['choice']['title'] == 'apta' and 'substitution' in pick and pick['cost'] == 0,
      pick.get('substitution', '—') + f" · custo {pick['cost']}")
ab = [f for f in os.listdir(f'{W}/ab')] if os.path.isdir(f'{W}/ab') else []
check('híbrido: A/B no mesmo trecho com loudness comparável', len(ab) >= 1, f'{ab} (só 1 faixa apta e grátis: a alternativa paga foi excluída pela verba 0)')

# ---------------------------------------------------------------- 3 mono cancellation vs intentional silence
run(PY, 'scripts/synth_music.py', f'{W}/base.wav', '--len', '8', '--drop', '4', '--breath', '0.3')
x = dec(f'{W}/base.wav').copy(); bad = x.copy(); i0, i1 = int(2.0 * SR), int(3.0 * SR)
bad[i0:i1, 1] = -bad[i0:i1, 0]                                    # R = −L for one second: disappears when folded to mono
s0, s1 = int(5.5 * SR), int(6.3 * SR); bad[s0:s1] = 0; x[s0:s1] = 0  # declared silence in both
wav(f'{W}/mono-defeito.wav', bad); wav(f'{W}/mono-corrigido.wav', x)
to_mp4(f'{W}/mono-defeito.wav', f'{W}/mono-defeito.mp4', 8); to_mp4(f'{W}/mono-corrigido.wav', f'{W}/mono-corrigido.mp4', 8)
json.dump({'intentional': [{'type': 'silence', 'from': 5.5, 'to': 6.3, 'why': 'respiro'}]}, open(f'{W}/tl.json', 'w'))
c1, o1 = run(PY, 'scripts/qa_audio.py', 'deliver', f'{W}/mono-defeito.mp4', '--timeline', f'{W}/tl.json', '--json', f'{EV}/mono-defeito.json')
c2, o2 = run(PY, 'scripts/qa_audio.py', 'deliver', f'{W}/mono-corrigido.mp4', '--timeline', f'{W}/tl.json', '--json', f'{EV}/mono-corrigido.json')
r1, r2 = json.load(open(f'{EV}/mono-defeito.json', encoding='utf8')), json.load(open(f'{EV}/mono-corrigido.json', encoding='utf8'))
mono_found = [p for p in r1['problems'] if 'mono' in p]; mono_ok = any(p.startswith('cancelamento em mono 2.0') or p.startswith('cancelamento em mono 1.9') for p in mono_found)
check('mono: cancelamento achado no trecho defeituoso (MP4 decodificado)', c1 == 1 and mono_ok and not any('silêncio não declarado' in p for p in r1['problems']), '; '.join(mono_found))
check('mono: versão corrigida passa e o silêncio previsto continua aceito', not any('mono' in p for p in r2['problems']) and any('silêncio intencional' in n for n in r2['notes']), f"problemas {r2['problems']} · notas {r2['notes']}")

# ---------------------------------------------------------------- 4 voice keyword masked → music ducks in that interval
def voice_like(dur, words):   # harmonic source with formant-ish band and syllable envelope: a deterministic stand-in for speech
    n = int(dur * SR); t = np.arange(n) / SR; f0 = 140 + 20 * np.sin(2 * np.pi * 3 * t); ph = 2 * np.pi * np.cumsum(f0) / SR
    src = sum(np.sin(k * ph) / k for k in range(1, 30)); from scipy.signal import butter, sosfilt
    src = sosfilt(butter(2, [500 / (SR / 2), 3000 / (SR / 2)], 'band', output='sos'), src); envv = np.zeros(n)
    for a, b in words: i, j = int(a * SR), int(b * SR); envv[i:j] = np.sin(np.linspace(0, np.pi, j - i)) ** 0.5 * (0.6 + 0.4 * np.abs(np.sin(np.linspace(0, 9, j - i))))
    return src / np.abs(src).max() * envv * 0.32
words = [(9.2, 9.7), (9.8, 10.6)]   # "Ressoa" + "R1" → the key word is 9.8–10.6 (on the drop's energy)
vo = voice_like(21, words); wav(f'{W}/voz.wav', vo)
run(PY, 'scripts/synth_music.py', f'{W}/musica-sem-recuo.wav', '--len', '21', '--drop', '9', '--seed', '2')
run(PY, 'scripts/synth_music.py', f'{W}/musica-com-recuo.wav', '--len', '21', '--drop', '9', '--seed', '2', '--voice-gap', '9.1-10.8:12')
c1, _ = run(PY, 'scripts/qa_audio.py', 'masking', '--voice', f'{W}/voz.wav', '--bed', f'{W}/musica-sem-recuo.wav', '--word', '9.8-10.6', '--json', f'{EV}/voz-antes.json')
c2, _ = run(PY, 'scripts/qa_audio.py', 'masking', '--voice', f'{W}/voz.wav', '--bed', f'{W}/musica-com-recuo.wav', '--word', '9.8-10.6', '--json', f'{EV}/voz-depois.json')
va, vb = json.load(open(f'{EV}/voz-antes.json', encoding='utf8')), json.load(open(f'{EV}/voz-depois.json', encoding='utf8'))
ma, mb = dec(f'{W}/musica-sem-recuo.wav'), dec(f'{W}/musica-com-recuo.wav'); outside = float(np.abs(ma[:int(8.9 * SR)] - mb[:int(8.9 * SR)]).max())
check('voz: palavra-chave encoberta → a música recua só no intervalo', c1 == 1 and c2 == 0 and outside == 0.0,
      f"SNR da palavra {va['words'][0]['snr_db']} → {vb['words'][0]['snr_db']} dB (mín 6); música idêntica fora do intervalo (dif {outside})")

# ---------------------------------------------------------------- 5 timbre revision: "menos estridente"
lib = f'{W}/lib'; os.makedirs(lib)
n = int(0.18 * SR); t = np.arange(n) / SR
conf = (np.sin(2 * np.pi * 2400 * t) + 0.6 * np.sin(2 * np.pi * 4800 * t) + 0.4 * np.sin(2 * np.pi * 7200 * t)) * np.exp(-t * 28) * 0.5
conf[:int(0.0015 * SR)] *= np.linspace(0, 1, int(0.0015 * SR))
wav(f'{lib}/confirmacao.wav', conf); wav(f'{lib}/toque.wav', np.sin(2 * np.pi * 300 * t) * np.exp(-t * 40) * 0.6)
shutil.copy(f'{W}/base.wav', f'{lib}/cama.wav')
ev = [{'name': 'toque', 't': 1.2}, {'name': 'confirmado', 't': 2.4}]; json.dump(ev, open(f'{W}/events.json', 'w'))
cues = [{'type': 'bed', 'file': 'cama', 'at': 0, 'to': 8, 'db': -18, 'stem': 'musica'},
        {'event': 'toque', 'file': 'toque', 'db': -8, 'align': 'start', 'stem': 'foley'},
        {'event': 'confirmado', 'file': 'confirmacao', 'db': -8, 'align': 'start', 'stem': 'ui'}]
json.dump(cues, open(f'{W}/cues-v1.json', 'w')); cues2 = json.loads(json.dumps(cues)); cues2[2]['lp'] = 3500   # ONE variable: the cue's highs
json.dump(cues2, open(f'{W}/cues-v2.json', 'w'))
for v in ('v1', 'v2'):
    c, o = run(PY, 'scripts/mix.py', f'{W}/cues-{v}.json', f'{W}/mix-{v}.wav', '--lib', lib, '--events', f'{W}/events.json', '--len', '8', '--stems', f'{W}/stems-{v}')
    to_mp4(f'{W}/mix-{v}.wav', f'{W}/confirmacao-{v}.mp4', 8)
c, o = run(PY, 'scripts/qa_audio.py', 'onset', f'{W}/confirmacao-v1.mp4', f'{W}/confirmacao-v2.mp4', '--at', '2.4', '--win', '0.1', '--json', f'{EV}/timbre-onset.json')
on = json.load(open(f'{EV}/timbre-onset.json', encoding='utf8'))
same = all(np.array_equal(dec(f'{W}/stems-v1/{s}.wav'), dec(f'{W}/stems-v2/{s}.wav')) for s in ('musica', 'foley'))
def centroid(p):
    y = dec(p, 1)[:, 0]; f = np.abs(np.fft.rfft(y * np.hanning(len(y)))); fr = np.fft.rfftfreq(len(y), 1 / SR); return float((f * fr).sum() / (f.sum() + 1e-9))
c1, c2 = centroid(f'{W}/stems-v1/ui.wav'), centroid(f'{W}/stems-v2/ui.wav')
check('timbre: confirmação menos estridente, contato estável no MP4 decodificado, outros stems idênticos',
      abs(on['delta_ms']) <= 1.0 and same and c2 < c1 * 0.8, f"onset {on['a']} → {on['b']} s (Δ {on['delta_ms']} ms); centróide {c1:.0f} → {c2:.0f} Hz; música e foley bit a bit iguais: {same}")
# peak-alignment risk: aligning by peak after a filter can move the contact — measured, not assumed
cues3 = json.loads(json.dumps(cues2)); cues3[2]['align'] = 'peak'; json.dump(cues3, open(f'{W}/cues-v3.json', 'w'))
run(PY, 'scripts/mix.py', f'{W}/cues-v3.json', f'{W}/mix-v3.wav', '--lib', lib, '--events', f'{W}/events.json', '--len', '8'); to_mp4(f'{W}/mix-v3.wav', f'{W}/confirmacao-v3.mp4', 8)
c, o = run(PY, 'scripts/qa_audio.py', 'onset', f'{W}/confirmacao-v1.mp4', f'{W}/confirmacao-v3.mp4', '--at', '2.4', '--win', '0.1')
d3 = json.loads(o[o.index('{'):])['delta_ms']
check('timbre: risco do alinhamento por pico conferido explicitamente', True, f'com align "peak" o contato andaria {d3} ms; a revisão usa align "start" (Δ {on["delta_ms"]} ms)')
for f in ('confirmacao-v1.mp4', 'confirmacao-v2.mp4'): shutil.copy(f'{W}/{f}', f'{EV}/{f}')

json.dump(res, open(f'{EV}/RESUMO.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
print(f"\n{sum(r['result'] == 'PASSOU' for r in res)}/{len(res)} passaram"); sys.exit(0 if all(r['result'] == 'PASSOU' for r in res) else 1)
